with cleaned as (select id, promo_code, discount_pct, coalesce(channel, 'N/A') as channel_filled from promotions where channel is not null and channel <> 'store'), scored as (select *, avg(discount_pct) over (partition by promo_code order by discount_pct, id rows between 5 preceding and current row) as discount_pct_avg_5, cume_dist() over (partition by promo_code order by discount_pct desc) as discount_pct_cume_dist from cleaned), cleaned_promotions as (select id, promo_code, discount_pct, channel_filled, discount_pct_avg_5, discount_pct_cume_dist, case when discount_pct_cume_dist >= 0.73 then 'High' when discount_pct_cume_dist >= 0.18 then 'Medium' else 'Low' end as discount_pct_cume_dist_level from scored where discount_pct between 0.29 and 0.31), with_windows as (select *, first_value(discount_pct_cume_dist, true) over (order by discount_pct_cume_dist, id rows between unbounded preceding and current row) as first_known_discount_pct_cume_dist, round(discount_pct_avg_5 / sum(discount_pct_avg_5) over (partition by promo_code), 4) as discount_pct_avg_5_share, last_value(discount_pct_avg_5, true) over (partition by promo_code order by discount_pct, id rows between unbounded preceding and current row) as last_known_discount_pct_avg_5 from cleaned_promotions), cleaned_promotions_2 as (select *, lower(promo_code) as promo_code_lower, last_known_discount_pct_avg_5 - discount_pct_avg_5 as last_known_discount_pct_avg_5_minus_discount_pct_avg_5 from with_windows where discount_pct_cume_dist > 0.6), enriched as (select id, promo_code, discount_pct, discount_pct_avg_5, discount_pct_cume_dist, last_known_discount_pct_avg_5, promo_code_lower, row_number() over (partition by promo_code order by discount_pct_avg_5 desc, id) as event_seq, row_number() over (order by last_known_discount_pct_avg_5_minus_discount_pct_avg_5 desc, id) as event_seq_2, avg(last_known_discount_pct_avg_5) over (partition by promo_code order by discount_pct_avg_5, id rows between 6 preceding and current row) as last_known_discount_pct_avg_5_avg_6 from cleaned_promotions_2), ranked as (select *, row_number() over (partition by promo_code order by discount_pct_cume_dist desc, id) as latest_rank from enriched qualify latest_rank = 1) select case when last_known_discount_pct_avg_5 >= 0 then 'HIGH' else 'LOW' end as last_known_discount_pct_avg_5_tier, case when last_known_discount_pct_avg_5_avg_6 >= 0 then 'PREMIUM' else 'STANDARD' end as last_known_discount_pct_avg_5_avg_6_tier, count_if(promo_code = 'WELCOME5') as welcome5_events, sum(case when promo_code = 'SPRING10' then event_seq else 0 end) as spring10_event_seq, grouping_id() as grouping_level from ranked group by grouping sets ((case when last_known_discount_pct_avg_5 >= 0 then 'HIGH' else 'LOW' end, case when last_known_discount_pct_avg_5_avg_6 >= 0 then 'PREMIUM' else 'STANDARD' end), (case when last_known_discount_pct_avg_5 >= 0 then 'HIGH' else 'LOW' end), ());
